bgGrad.addColorStop(0, '#1a4a5c'); bgGrad.addColorStop(0.5, '#0f2d3a'); bgGrad.addColorStop(1, '#081820');
bgCtx.fillStyle = bgGrad; bgCtx.fillRect(0, 0, 2, 512);
